    { date: "1893", title: "Riforma bancaria e crisi siciliana", text: "Nasce la Banca d'Italia; Giolitti cade; Crispi torna al governo.", scale: "Italia/Sicilia" },
    { date: "3 gennaio 1894", title: "Stato d'assedio in Sicilia", text: "Esercito, scioglimento dei Fasci e tribunali militari segnano la nuova linea dell'ordine pubblico.", scale: "Sicilia" },
    { date: "1895", title: "La guerra d'Etiopia si allarga", text: "Amba Alagi mostra la capacità militare etiopica e aumenta la pressione politica per una vittoria italiana.", scale: "Africa" },
    { date: "1 marzo 1896", title: "Adua", text: "L'esercito di Menelik sconfigge le forze italiane; Crispi si dimette.", scale: "Africa/Italia" },
    { date: "1898", title: "Caro pane e repressione", text: "Moti in varie città; a Milano Bava Beccaris impiega anche l'artiglieria.", scale: "Italia" },
    { date: "1899", title: "Pelloux e ostruzionismo", text: "I provvedimenti restrittivi sulle libertà producono una lunga crisi parlamentare.", scale: "Italia" },
    { date: "1900", title: "Cassazione, elezioni e regicidio", text: "La stretta di Pelloux fallisce; Umberto I viene ucciso da Gaetano Bresci.", scale: "Italia" },
    { date: "1901", title: "Zanardelli-Giolitti", text: "Si apre una fase più liberale nella gestione delle organizzazioni e dei conflitti del lavoro.", scale: "Italia" }
